task get_pairs_count(arr: seq, target: int, count: int) returns (r: int)
  requires len(arr) >= 0
  ensures r == count
{
  r := 0;
  var i: int := 0;
  var j: int := 1;
  while i < len(arr) and j < len(arr)
    invariant 0 <= i and i < j and j <= len(arr)
    invariant r == count
    decreases j - i
  {
    var sum: int := arr[i] + arr[j];
    if sum == target {
      r := r + 1;
    }
    j := j + 1;
  }
}
